env -i PATH=/usr/bin:/bin LANG=C.UTF-8 LC_ALL=C.UTF-8 TZ=UTC /usr/bin/python3.10 -I -S -B -c 'import hashlib,json,re,stat
from pathlib import Path
P=Path("/root/autodl-tmp/symbolic_dynamics/docs/papers211_215_sequence/scouting/finite_parking_allocation_scout01")
expected={"INTAKE.md","PROOF_AND_SUBTRACTION.md","REPORT.md","NATIVE_READS.json","WEB_REQUESTS.json","INPUTS.sha256"}
assert {p.name for p in P.iterdir()}==expected
def pin(raw):return {"bytes":len(raw),"sha256":hashlib.sha256(raw).hexdigest()}
pins={}
for p in P.iterdir():
 s=p.lstat();assert stat.S_ISREG(s.st_mode) and s.st_nlink==1
 pins[p.name]=pin(p.read_bytes())
links=[]
for name in ("INTAKE.md","PROOF_AND_SUBTRACTION.md","REPORT.md"):
 raw=(P/name).read_text()
 for h in re.findall(r"\[[^\]]*\]\(([^)]+)\)",raw):
  if re.match(r"^[a-z]+:",h):continue
  q=h.split("#",1)[0]
  if q in ("CLOSING_NATIVE.json","SHA256SUMS"):
   assert not (P/q).exists()
   links.append({"origin":name,"href":h,"status":"exact_pending_final_appendix"})
  else:
   assert (P/q).resolve(strict=True).is_file()
   links.append({"origin":name,"href":h,"status":"exists"})
manifest=(P/"INPUTS.sha256").read_text()
rows=manifest.splitlines();assert len(rows)==15
for line in rows:
 m=re.fullmatch(r"([0-9a-f]{64})  (/.+)",line);assert m
 h,q=m.groups();assert hashlib.sha256(Path(q).read_bytes()).hexdigest()==h
assert all(pin((P/name).read_bytes())==v for name,v in pins.items())
print(json.dumps({"status":"PASS_SIX_PRESEAL_PAYLOADS_AND_ALL_LOCAL_LINKS_INPUT15","payloads":len(pins),"payload_bytes":sum(v["bytes"] for v in pins.values()),"payload_pins":pins,"local_links":links,"report_first_preseal_pin":pins["REPORT.md"],"allowed_next_appends":["CLOSING_NATIVE.json","SHA256SUMS"],"science":False,"candidate_execution":False},sort_keys=True,indent=2))
